source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    seen = set()
    candidates = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == background or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                        (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            bottom = max(y for y, x in component)
            rightmost = max(x for y, x in component if y == bottom)
            if rightmost < w - 1 and all(grid[bottom][x] == background for x in range(rightmost + 1, w)):
                candidates.append((bottom, rightmost))
    # Extend the trailing background after the rightmost terminal component(s).
    if candidates:
        farthest = max(c for r, c in candidates)
        for r, c in candidates:
            if c >= farthest - 1:
                for x in range(c + 1, w):
                    out[r][x] = 1
    return out
'''
